import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        vm.assume(contract_address != address(0) && contract_address != address(c));
        // Ensure the external call will succeed: we need a contract at contract_address that accepts transferFrom
        // For simplicity, we deploy a dummy contract that always returns true
        // This is a cheat: we can't deploy inside a fuzz test easily, so we assume the call will revert if not handled.
        // Instead, we wrap the call in try/catch and check the return value only when it doesn't revert.
        try c.transfer(contract_address, tos, vs) returns (bool result) {
