// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        // Transfer will revert if any call to contract_address fails, or if looping out of bounds
        (bool success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, contract_address, tos, vs));
        // The reference should always succeed for valid inputs; the mutant may revert due to out-of-bounds
        assertTrue(success);
    }
}
